using LibreKO.Common.Domain.Entities.GameData;
using LibreKO.Common.Infrastructure.Persistence;
using LibreKO.Editors.Contracts;
using LibreKO.Editors.DataHost;
using LibreKO.Editors.DataHost.Events;
using Microsoft.EntityFrameworkCore;
using MySqlConnector;
public class EventReadTests {
 const string Cs="Server=127.0.0.1;Port=33307;Database=libreko_editor_test_native;User=root;Pooling=false;";
 [Fact] public async Task ReadEachFamilyWithFullIdentityAndNoWrites(){await using var db=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseMySql(Cs,new MySqlServerVersion(new Version(8,2,0))).Options);await db.Database.EnsureCreatedAsync();const int id=861001;await db.GameEvents.Where(r=>r.EventNum==30001&&(r.ZoneNum==201||r.ZoneNum==202)).ExecuteDeleteAsync();db.GameEvents.AddRange(new GameEventData{ZoneNum=201,EventNum=30001,Type=1,Exec1=1},new GameEventData{ZoneNum=202,EventNum=30001,Type=3});if(!await db.CollectionRaces.AnyAsync(r=>r.Id==id))db.CollectionRaces.Add(new CollectionRaceData{Id=id,Name="event_read_fixture",ZoneId=201,MinLevel=1,MaxLevel=83});if(!await db.LotteryEvents.AnyAsync(r=>r.Id==id))db.LotteryEvents.Add(new LotteryEventData{Id=id,Name="event_read_fixture"});if(!await db.SiegeWarfare.AnyAsync(r=>r.CastleIndex==30001))db.SiegeWarfare.Add(new SiegeWarfareData{CastleIndex=30001,WarDay=1});if(!await db.MapObjects.AnyAsync(r=>r.Id==id))db.MapObjects.Add(new MapObjectData{Id=id,ZoneId=201,Index=30001,Type=0});if(!await db.EventTriggers.AnyAsync(r=>r.Index==id))db.EventTriggers.Add(new EventTriggerData{Index=id,NpcId=42,TriggerNum=17});if(!await db.ForgottenTempleWaves.AnyAsync(r=>r.Id==id))db.ForgottenTempleWaves.Add(new ForgottenTempleWaveData{Id=id,Tier=1,Wave=1,Count=1,NpcId=1});await db.SaveChangesAsync();var count=await db.GameEvents.CountAsync();var service=new EventDatabase(Cs,Path.Combine(Path.GetTempPath(),"event-read-"+Guid.NewGuid()));var support=await service.CheckCompatibilityAsync();Assert.Equal(14,support.Tables.Count);Assert.All(support.Tables,t=>Assert.True(t.CanSave,t.Reason));Assert.DoesNotContain(support.Tables.SelectMany(t=>t.Issues),i=>i.Code=="schema.lookup");foreach(var family in Enum.GetValues<EventFamily>()){var page=await service.ListAsync(family,new(Size:1));Assert.NotEmpty(page.Rows);Assert.InRange(page.Rows.Count,1,1);}Assert.NotEqual((await service.GetAsync(new(EventFamily.MapEvent,30001,201)))!.Version,(await service.GetAsync(new(EventFamily.MapEvent,30001,202)))!.Version);Assert.Contains((await service.GetAsync(new(EventFamily.Temple,5)))!.Rows,r=>r.Key.Table==EventTable.ForgottenTempleWaves);Assert.DoesNotContain((await service.GetAsync(new(EventFamily.Temple,1)))!.Rows,r=>r.Key.Table==EventTable.ForgottenTempleWaves);Assert.Equal(count,await db.GameEvents.CountAsync());Assert.True(await service.NextIdAsync(EventTable.GameEvents,201)>=2);}
 [Fact] public async Task SchemaFaultsAreScopedAndPrecedeProjection(){var name="libreko_editor_test_events_"+Guid.NewGuid().ToString("N");await using var c=new MySqlConnection(Cs);await c.OpenAsync();await new MySqlCommand("CREATE DATABASE `"+name+"`",c).ExecuteNonQueryAsync();try{await new MySqlCommand("CREATE TABLE `"+name+"`.GameEvents(ZoneNum tinyint unsigned NOT NULL, EventNum smallint NOT NULL, PRIMARY KEY(ZoneNum,EventNum)) ENGINE=MyISAM",c).ExecuteNonQueryAsync();var service=new EventDatabase(new MySqlConnectionStringBuilder(Cs){Database=name}.ConnectionString,Path.GetTempPath());var report=await service.CheckCompatibilityAsync();var support=report.Tables.Single(t=>t.Table==EventTable.GameEvents);Assert.False(support.CanBrowse);Assert.False(support.CanSave);Assert.Contains(support.Issues,i=>i.Code=="schema.column");Assert.Contains(support.Issues,i=>i.Code=="schema.engine");var error=await Assert.ThrowsAsync<InvalidOperationException>(()=>service.GetAsync(new(EventFamily.MapEvent,7,1)));Assert.Contains("structure",error.Message,StringComparison.OrdinalIgnoreCase);}finally{await new MySqlCommand("DROP DATABASE `"+name+"`",c).ExecuteNonQueryAsync();}}
 [Fact] public async Task NpcSearchAndResolveUsesPrototypeId(){await using var db=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseMySql(Cs,new MySqlServerVersion(new Version(8,2,0))).Options);await db.Database.EnsureCreatedAsync();if(!await db.Npcs.AnyAsync(r=>r.Id==861001)){db.Npcs.Add(new NpcData{Id=861001,Name="event_npc_fixture"});await db.SaveChangesAsync();}var content=new EditorDatabase(Cs,Path.GetTempPath());Assert.Equal(861001,Assert.Single((await content.LookupAsync(new("npcs","event_npc_fixture"))).Rows).Id);Assert.Equal("event_npc_fixture",Assert.Single((await content.LookupAsync(new("npcs"),[861001])).Rows).Label);}
 [Fact] public async Task IncompatibleTypeAndMissingOptionalLookupAreScoped(){
  var name="libreko_editor_test_events_"+Guid.NewGuid().ToString("N");await using var c=new MySqlConnection(Cs);await c.OpenAsync();await new MySqlCommand("CREATE DATABASE `"+name+"`",c).ExecuteNonQueryAsync();
  try{foreach(var table in new[]{"GameEvents","TempleEventSchedules","TempleEventRewards"})await new MySqlCommand("CREATE TABLE `"+name+"`."+table+" LIKE libreko_editor_test_native."+table,c).ExecuteNonQueryAsync();await new MySqlCommand("ALTER TABLE `"+name+"`.GameEvents MODIFY Type varchar(40) NOT NULL",c).ExecuteNonQueryAsync();var service=new EventDatabase(new MySqlConnectionStringBuilder(Cs){Database=name}.ConnectionString,Path.GetTempPath());var report=await service.CheckCompatibilityAsync();Assert.False(report.Tables.Single(t=>t.Table==EventTable.GameEvents).CanBrowse);Assert.Contains(report.Tables.SelectMany(t=>t.Issues),i=>i.Code=="schema.lookup");Assert.NotNull(await service.GetAsync(new(EventFamily.Temple,1)));await Assert.ThrowsAsync<InvalidOperationException>(()=>service.GetAsync(new(EventFamily.Temple,5)));await Assert.ThrowsAsync<InvalidOperationException>(()=>service.GetAsync(new(EventFamily.MapEvent,2,1)));}
  finally{await new MySqlCommand("DROP DATABASE `"+name+"`",c).ExecuteNonQueryAsync();}
 }
}
